import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.net.HttpURLConnection;
import java.net.URI;
import java.net.URL;
import java.nio.charset.Charset;
import java.nio.charset.StandardCharsets;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class Main {
    private static final Pattern TITLE_PATTERN = Pattern.compile("<title[^>]*>(.*?)</title>", Pattern.CASE_INSENSITIVE | Pattern.DOTALL);
    private static final Pattern CHARSET_PATTERN = Pattern.compile("charset=([^;\\s]+)", Pattern.CASE_INSENSITIVE);
    private static final int MAX_REDIRECTS = 5;

    public static void main(String[] args) {
        if (args.length == 0) {
            System.err.println("Usage: java Main <https-url>");
            return;
        }
        try {
            String title = getPageTitle(args[0]);
            System.out.println(title == null ? "" : title);
        } catch (Exception e) {
            System.err.println("Error: " + e.getMessage());
        }
    }

    public static String getPageTitle(String url) throws IOException {
        String currentUrl = url;
        int redirectCount = 0;

        while (redirectCount <= MAX_REDIRECTS) {
            URL parsedUrl = new URL(currentUrl);
            HttpURLConnection connection = (HttpURLConnection) parsedUrl.openConnection();
            connection.setRequestMethod("GET");
            connection.setConnectTimeout(10000);
            connection.setReadTimeout(10000);
            connection.setInstanceFollowRedirects(false);
            connection.setRequestProperty("User-Agent", "Mozilla/5.0 (compatible; TitleFetcher/1.0)");

            int responseCode = connection.getResponseCode();

            if (responseCode >= 300 && responseCode < 400) {
                String location = connection.getHeaderField("Location");
                connection.disconnect();

                if (location == null || location.trim().isEmpty()) {
                    return null;
