                try {
                    currentUrl = new URI(currentUrl).resolve(location).toString();
                } catch (Exception e) {
                    throw new IOException("Unable to resolve redirect location", e);
                }

                redirectCount++;
                continue;
            }

            if (responseCode < 200 || responseCode >= 300) {
                connection.disconnect();
                return null;
            }

            Charset charset = getCharset(connection);
            String html = readBody(connection.getInputStream(), charset);
            connection.disconnect();

            return extractTitle(html);
        }

        return null;
    }

    private static Charset getCharset(HttpURLConnection connection) {
        String contentType = connection.getContentType();
        if (contentType != null) {
            Matcher matcher = CHARSET_PATTERN.matcher(contentType);
            if (matcher.find()) {
                try {
                    return Charset.forName(matcher.group(1).replace("\"", ""));
                } catch (Exception ignored) {
                    // Fall through to UTF-8.
                }
            }
        }
        return StandardCharsets.UTF_8;
    }

    private static String readBody(InputStream inputStream, Charset charset) throws IOException {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        byte[] chunk = new byte[8192];
        int bytesRead;

        try (InputStream in = inputStream) {
            while ((bytesRead = in.read(chunk)) != -1) {
                buffer.write(chunk, 0, bytesRead);
            }
        }

        return new String(buffer.toByteArray(), charset);
    }

