        if (html == null || html.isEmpty()) {
            return "";
        }

        Matcher matcher = TITLE_PATTERN.matcher(html);
        if (matcher.find()) {
            String title = matcher.group(1);
            title = decodeBasicHtmlEntities(title);
            return title.trim();
        }

        return "";
    }

    private static String decodeBasicHtmlEntities(String text) {
        return text
                .replace("&lt;", "<")
                .replace("&gt;", ">")
                .replace("&quot;", "\"")
                .replace("&#39;", "'")
                .replace("&nbsp;", " ")
                .replace("&amp;", "&");
